// RemoveEscalation relationship.
// Sets o.R.Escalation to nil.
// Removes o from all passed in related items' relationships struct.
func (o *NotificationRun) RemoveEscalation(ctx context.Context, exec boil.ContextExecutor, related *AlertEscalation) error {
	var err error

	queries.SetScanner(&o.EscalationID, nil)
	if _, err = o.Update(ctx, exec, boil.Whitelist("escalation_id")); err != nil {
		return errors.Wrap(err, "failed to update local table")
	}

	if o.R != nil {
		o.R.Escalation = nil
	}
	if related == nil || related.R == nil {
		return nil
	}

	for i, ri := range related.R.EscalationNotificationRuns {
		if queries.Equal(o.EscalationID, ri.EscalationID) {
			continue
		}

		ln := len(related.R.EscalationNotificationRuns)
		if ln > 1 && i < ln-1 {
			related.R.EscalationNotificationRuns[i] = related.R.EscalationNotificationRuns[ln-1]
		}
		related.R.EscalationNotificationRuns = related.R.EscalationNotificationRuns[:ln-1]
		break
	}
	return nil
}

